window.BOOK={"key":"hamasa","app":"mutoon-hamasa","lsk":"mutoon_hamasa_v1","prefix":"ha_","title":"العزة والحماسة","sub":"مختارات · من عنترة وقطري بن الفجاءة إلى المتنبي والبارودي · ١٩٠ بيتًا","poems":[{"id":"hamasa","title":"العزة والحماسة","nazim":"مختارات من عدة شعراء","death":"","meter":"الطويل والكامل والبسيط والوافر والخفيف ومجزوء الكامل","source":"دواوين الشعراء (موقع الديوان) وشرح ديوان الحماسة للتبريزي وشرح ديوان المتنبي للواحدي (المكتبة الشاملة)، مع الحماسة المغربية وجواهر الأدب والدر الفريد","srcUrl":"https://shamela.ws/book/6907","note":"أشهر وأقوى أبيات العزة والشجاعة والإباء والصبر من كل قصيدة (٢–٩ أبيات)، في خمسة أبواب: الإباء وعزة النفس، الشجاعة والإقدام، الصبر على الشدائد، علو الهمة، الوفاء والكرم. من شعر قطري بن الفجاءة وقريط بن أنيف وسعد بن ناشب والحصين بن الحمام وعمرو بن الإطنابة وعمرو بن معدي كرب وحاتم وعروة والمقنع الكندي والمتنبي وأبي تمام وعلي بن الجهم والشريف الرضي وصفي الدين الحلي والبارودي وغيرهم. كل مقطوعة منقولة من مصدر منشور وقوبلت كلمةً كلمةً بسكربت بمصدر ثانٍ وفُحص وزن كل شطر. لا توجد نشرة رقمية تامة الشكل لهذه المختارات: أُكمل شكل نصوص موقع الديوان آليًّا، وشُكلت ٨ مقطوعات (٥٥ بيتًا: قريط، سعد بن ناشب، المقنع، ابن كنيف، عمرو بن معدي كرب، تأبط شرًّا، ابن الإطنابة، البارودي) يدويًّا على حروف أساسها. ٢٠ بيتًا منقولة بنصها من متون التطبيق (لامية العرب، السموأل، المتنبي، أبو فراس، عمرو بن كلثوم، لامية العجم). ما ضعفت نسبته كُتب «المنسوب إلى…». التفصيل في تقرير المصادر (hamasa-sources.md).","verses":[["حَكِّمْ سُيُوفَكَ فِي رِقَابِ الْعُذَّلِ","وَإِذَا نَزَلْتَ بِدَارِ ذُلٍّ فَارْحَلِ"],["وَاخْتَرْ لِنَفْسِكَ مَنْزِلًا تَعْلُو بِهِ","أَوْ مُتْ كَرِيمًا تَحْتَ ظِلِّ الْقَسْطَلِ"],["فَالْمَوْتُ لَا يُنْجِيكَ مِنْ آفَاتِهِ","حِصْنٌ وَلَوْ شَيَّدْتَهُ بِالْجَنْدَلِ"],["مَوْتُ الْفَتَى فِي عِزَّةٍ خَيْرٌ لَهُ","مِنْ أَنْ يَبِيتَ أَسِيرَ طَرْفٍ أَكْحَلِ"],["إِنْ كُنْتُ فِي عَدَدِ الْعَبِيدِ فَهِمَّتِي","فَوْقَ الثُّرَيَّا وَالسِّمَاكِ الْأَعْزَلِ"],["أَوْ أَنْكَرَتْ فُرْسَانُ عَبْسٍ نِسْبَتِي","فَسِنَانُ رُمْحِي وَالْحُسَامُ يُقِرُّ لِي"],["وَبِذَابِلِي وَمُهَنَّدِي نِلْتُ الْعُلَا","لَا بِالْقَرَابَةِ وَالْعَدِيدِ الْأَجْزَلِ"],["لَا تَسْقِنِي مَاءَ الْحَيَاةِ بِذِلَّةٍ","بَلْ فَاسْقِنِي بِالْعِزِّ كَأْسَ الْحَنْظَلِ"],["مَاءُ الْحَيَاةِ بِذِلَّةٍ كَجَهَنَّمٍ","وَجَهَنَّمٌ بِالْعِزِّ أَطْيَبُ مَنْزِلِ"],["عِشْ عَزِيزًا أَوْ مُتْ وَأَنْتَ كَرِيمٌ","بَيْنَ طَعْنِ الْقَنَا وَخَفْقِ الْبُنُودِ"],["فَرُؤُوسُ الرِّمَاحِ أَذْهَبُ لِلْغَيْـ","ـظِ وَأَشْفَى لِغِلِّ صَدْرِ الْحَقُودِ"],["لَا كَمَا قَدْ حَيِيتَ غَيْرَ حَمِيدٍ","وَإِذَا مُتَّ مُتَّ غَيْرَ فَقِيدِ"],["فَاطْلُبِ الْعِزَّ فِي لَظَى وَذَرِ الذُّلْـ","ـلَ وَلَوْ كَانَ فِي جِنَانِ الْخُلُودِ"],["يُقْتَلُ الْعَاجِزُ الْجَبَانُ وَقَدْ يَعْـ","ـجِزُ عَنْ قَطْعِ بُخْنُقِ الْمَوْلُودِ"],["وَيُوَقَّى الْفَتَى الْمِخَشُّ وَقَدْ خَوْـ","ـوَضَ فِي مَاءِ لَبَّةِ الصِّنْدِيدِ"],["لَا بِقَوْمِي شَرُفْتُ بَلْ شَرُفُوا بِي","وَبِنَفْسِي فَخَرْتُ لَا بِجُدُودِي"],["لَا افْتِخَارٌ إِلَّا لِمَنْ لَا يُضَامُ","مُدْرِكٍ أَوْ مُحَارِبٍ لَا يَنَامُ"],["لَيْسَ عَزْمًا مَا مَرَّضَ الْمَرْءُ فِيهِ","لَيْسَ هَمًّا مَا عَاقَ عَنْهُ الظَّلَامُ"],["وَاحْتِمَالُ الْأَذَى وَرُؤْيَةُ جَانِيـ","ـهِ غِذَاءٌ تَضْوَى بِهِ الْأَجْسَامُ"],["ذَلَّ مَنْ يَغْبِطُ الذَّلِيلَ بِعَيْشٍ","رُبَّ عَيْشٍ أَخَفُّ مِنْهُ الْحِمَامُ"],["كُلُّ حِلْمٍ أَتَى بِغَيْرِ اقْتِدَارٍ","حُجَّةٌ لَاجِئٌ إِلَيْهَا اللِّئَامُ"],["مَنْ يَهُنْ يَسْهُلِ الْهَوَانُ عَلَيْهِ","مَا لِجُرْحٍ بِمَيِّتٍ إِيلَامُ"],["لَوْ كُنْتُ مِنْ مَازِنٍ لَمْ تَسْتَبِحْ إِبِلِي","بَنُو اللَّقِيطَةِ مِنْ ذُهْلِ بْنِ شَيْبَانَا"],["إِذَنْ لَقَامَ بِنَصْرِي مَعْشَرٌ خُشُنٌ","عِنْدَ الْحَفِيظَةِ إِنْ ذُو لُوثَةٍ لَانَا"],["قَوْمٌ إِذَا الشَّرُّ أَبْدَى نَاجِذَيْهِ لَهُمْ","طَارُوا إِلَيْهِ زَرَافَاتٍ وَوُحْدَانَا"],["لَا يَسْأَلُونَ أَخَاهُمْ حِينَ يَنْدُبُهُمْ","فِي النَّائِبَاتِ عَلَى مَا قَالَ بُرْهَانَا"],["لَكِنَّ قَوْمِي وَإِنْ كَانُوا ذَوِي عَدَدٍ","لَيْسُوا مِنَ الشَّرِّ فِي شَيْءٍ وَإِنْ هَانَا"],["يَجْزُونَ مِنْ ظُلْمِ أَهْلِ الظُّلْمِ مَغْفِرَةً","وَمِنْ إِسَاءَةِ أَهْلِ السُّوءِ إِحْسَانَا"],["كَأَنَّ رَبَّكَ لَمْ يَخْلُقْ لِخَشْيَتِهِ","سِوَاهُمُ مِنْ جَمِيعِ النَّاسِ إِنْسَانَا"],["فَلَيْتَ لِي بِهِمُ قَوْمًا إِذَا رَكِبُوا","شَدُّوا الْإِغَارَةَ فُرْسَانًا وَرُكْبَانَا"],["وَفِي الأَرْضِ مَنْأًى لِلْكَرِيمِ عَنِ الأَذَى","وَفِيهَا لِمَنْ خَافَ القِلَى مُتَعَزَّلُ"],["أُدِيمُ مِطَالَ الْجُوعِ حَتَّى أُمِيتَهُ","وأَضْرِبُ عَنْهُ الذِّكْرَ صَفْحًا فأَذْهَلُ"],["وَأَسْتَفُّ تُرْبَ الأَرْضِ كَيْلا يَرَى لَهُ","عَلَيَّ مِنَ الطَّوْلِ امْرُؤٌ مُتَطَوِّلُ"],["لِغَيْرِ الْعُلَى مِنِّي الْقِلَى وَالتَّجَنُّبُ","وَلَوْلَا الْعُلَى مَا كُنْتُ فِي الْحُبِّ أَرْغَبُ"],["إِذَا اللَّهُ لَمْ يَعْذُرْكَ فِيمَا تَرُومُهُ","فَمَا النَّاسُ إِلَّا عَاذِلٌ أَوْ مُؤَنِّبُ"],["فَإِنْ تَكُ سِنِّي مَا تَطَاوَلَ بَاعُهَا","فَلِي مِنْ وَرَاءِ الْمَجْدِ قَلْبٌ مُدَرَّبُ"],["فَحَسْبِيَ أَنِّي فِي الْأَعَادِي مُبَغَّضٌ","وَأَنِّي إِلَى غُرِّ الْمَعَالِي مُحَبَّبُ"],["وَلِلْحِلْمِ أَوْقَاتٌ وَلِلْجَهْلِ مِثْلُهَا","وَلَكِنَّ أَوْقَاتِي إِلَى الْحِلْمِ أَقْرَبُ"],["يَصُولُ عَلَيَّ الْجَاهِلُونَ وَأَعْتَلِي","وَيُعْجِمُ فِيَّ الْقَائِلُونَ وَأُعْرِبُ"],["يَرَوْنَ احْتِمَالِي غَصَّةً وَيَزِيدُهُمْ","لَوَاعِجَ ضَغْنٍ أَنَّنِي لَسْتُ أَغْضَبُ"],["أَنَا إِنْ عِشْتُ لَسْتُ أَعْدَمُ قُوتًا","وَإِذَا مُتُّ لَسْتُ أَعْدَمُ قَبْرَا"],["هِمَّتِي هِمَّةُ الْمُلُوكِ وَنَفْسِي","نَفْسُ حُرٍّ تَرَى الْمَذَلَّةَ كُفْرَا"],["وَإِذَا مَا قَنِعْتُ بِالْقُوتِ عُمْرِي","فَلِمَاذَا أَزُورُ زَيْدًا وَعَمْرَا"],["إِذَا الْمَرْءُ لَمْ يَدْنَسْ مِنَ اللُّؤْمِ عِرْضُهُ","فَكُلُّ رِدَاءٍ يَرْتَدِيهِ جَمِيلُ"],["وَإِنْ هُوَ لَمْ يَحْمِلْ عَلَى النَّفْسِ ضَيْمَهَا","فَلَيْسَ إِلَى حُسْنِ الثَّنَاءِ سَبِيلُ"],["تُعَيِّرُنَا أَنَّا قَلِيلٌ عَدِيدُنَا","فَقُلْتُ لَهَا إِنَّ الْكِرَامَ قَلِيلُ"],["أَقُولُ لَهَا وَقَدْ طَارَتْ شَعَاعًا","مِنَ الْأَبْطَالِ وَيْحَكِ لَنْ تُرَاعِي"],["فَإِنَّكِ لَوْ سَأَلْتِ بَقَاءَ يَوْمٍ","عَلَى الْأَجَلِ الَّذِي لَكِ لَمْ تُطَاعِي"],["فَصَبْرًا فِي مَجَالِ الْمَوْتِ صَبْرًا","فَمَا نَيْلُ الْخُلُودِ بِمُسْتَطَاعِ"],["وَلَا ثَوْبُ الْبَقَاءِ بِثَوْبِ عِزٍّ","فَيُطْوَى عَنْ أَخِي الْخَنَعِ الْيَرَاعِ"],["سَبِيلُ الْمَوْتِ غَايَةُ كُلِّ حَيٍّ","فَدَاعِيهِ لِأَهْلِ الْأَرْضِ دَاعِي"],["وَمَنْ لَا يُعْتَبَطْ يَسْأَمْ وَيَهْرَمْ","وَتُسْلِمْهُ الْمَنُونُ إِلَى انْقِطَاعِ"],["وَمَا لِلْمَرْءِ خَيْرٌ فِي حَيَاةٍ","إِذَا مَا عُدَّ مِنْ سَقَطِ الْمَتَاعِ"],["تَأَخَّرْتُ أَسْتَبْقِي الْحَيَاةَ فَلَمْ أَجِدْ","لِنَفْسِي حَيَاةً مِثْلَ أَنْ أَتَقَدَّمَا"],["فَلَسْتُ بِمُبْتَاعِ الْحَيَاةِ بِسُبَّةٍ","وَلَا مُبْتَغٍ مِنْ رَهْبَةِ الْمَوْتِ سُلَّمَا"],["فَلَسْنَا عَلَى الْأَعْقَابِ تَدْمَى كُلُومُنَا","وَلَكِنْ عَلَى أَقْدَامِنَا تَقْطُرُ الدِّمَا"],["أَبَتْ لِي عِفَّتِي وَأَبَى بَلَائِي","وَأَخْذِي الْحَمْدَ بِالثَّمَنِ الرَّبِيحِ"],["وَإِمْسَاكِي عَلَى الْمَكْرُوهِ نَفْسِي","وَضَرْبِي هَامَةَ الْبَطَلِ الْمُشِيحِ"],["وَقَوْلِي كُلَّمَا جَشَأَتْ وَجَاشَتْ","مَكَانَكِ تُحْمَدِي أَوْ تَسْتَرِيحِي"],["لِأَدْفَعَ عَنْ مَآثِرَ صَالِحَاتٍ","وَأَحْمِي بَعْدُ عَنْ عِرْضٍ صَحِيحِ"],["سَأَغْسِلُ عَنِّي الْعَارَ بِالسَّيْفِ جَالِبًا","عَلَيَّ قَضَاءُ اللَّهِ مَا كَانَ جَالِبَا"],["وَأَذْهَلُ عَنْ دَارِي وَأَجْعَلُ هَدْمَهَا","لِعِرْضِيَ مِنْ بَاقِي الْمَذَمَّةِ حَاجِبَا"],["وَيَصْغُرُ فِي عَيْنِي تِلَادِي إِذَا انْثَنَتْ","يَمِينِي بِإِدْرَاكِ الَّذِي كُنْتُ طَالِبَا"],["فَإِنْ تَهْدِمُوا بِالْغَدْرِ دَارِي فَإِنَّهَا","تُرَاثُ كَرِيمٍ لَا يُبَالِي الْعَوَاقِبَا"],["أَخِي غَمَرَاتٍ لَا يُرِيدُ عَلَى الَّذِي","يَهُمُّ بِهِ مِنْ مُفْظِعِ الْأَمْرِ صَاحِبَا"],["إِذَا هَمَّ أَلْقَى بَيْنَ عَيْنَيْهِ عَزْمَهُ","وَنَكَّبَ عَنْ ذِكْرِ الْعَوَاقِبِ جَانِبَا"],["وَلَمْ يَسْتَشِرْ فِي أَمْرِهِ غَيْرَ نَفْسِهِ","وَلَمْ يَرْضَ إِلَّا قَائِمَ السَّيْفِ صَاحِبَا"],["إِنَّا بَنِي نَهْشَلٍ لَا نَدَّعِي لِأَبٍ","عَنْهُ وَلَا هُوَ بِالْأَبْنَاءِ يَشْرِينَا"],["إِنْ تُبْتَدَرْ غَايَةٌ يَوْمًا لِمَكْرُمَةٍ","تَلْقَ السَّوَابِقَ مِنَّا وَالْمُصَلِّينَا"],["وَلَيْسَ يَهْلَكُ مِنَّا سَيِّدٌ أَبَدًا","إِلَّا افْتَلَيْنَا غُلَامًا سَيِّدًا فِينَا"],["إِنَّا لَنُرْخِصُ يَوْمَ الرَّوْعِ أَنْفُسَنَا","وَلَوْ نُسَامُ بِهَا فِي الْأَمْنِ أُغْلِينَا"],["بِيضٌ مَفَارِقُنَا تَغْلِي مَرَاجِلُنَا","نَأْسُو بِأَمْوَالِنَا آثَارَ أَيْدِينَا"],["لَوْ كَانَ فِي الْأَلْفِ مِنَّا وَاحِدٌ فَدَعَوْا","مَنْ فَارِسٌ خَالَهُمْ إِيَّاهُ يَعْنُونَا"],["إِذَا الْكُمَاةُ تَنَحَّوْا أَنْ يُصِيبَهُمُ","حَدُّ الظُّبَاتِ وَصَلْنَاهَا بِأَيْدِينَا"],["الرَّأْيُ قَبْلَ شَجَاعَةِ الشُّجْعَانِ","هُوَ أَوَّلٌ وَهِيَ الْمَحَلُّ الثَّانِي"],["فَإِذَا هُمَا اجْتَمَعَا لِنَفْسٍ حُرَّةٍ","بَلَغَتْ مِنَ الْعَلْيَاءِ كُلَّ مَكَانِ"],["وَلَرُبَّمَا طَعَنَ الْفَتَى أَقْرَانَهُ","بِالرَّأْيِ قَبْلَ تَطَاعُنِ الْأَقْرَانِ"],["لَوْلَا الْعُقُولُ لَكَانَ أَدْنَى ضَيْغَمٍ","أَدْنَى إِلَى شَرَفٍ مِنَ الْإِنْسَانِ"],["وَلَمَا تَفَاضَلَتِ النُّفُوسُ وَدَبَّرَتْ","أَيْدِي الْكُمَاةِ عَوَالِيَ الْمُرَّانِ"],["وَمُرَادُ النُّفُوسِ أَصْغَرُ مِنْ أَنْ","نَتَعَادَى فِيهِ وَأَنْ نَتَفَانَى"],["غَيْرَ أَنَّ الْفَتَى يُلَاقِي الْمَنَايَا","كَالِحَاتٍ وَلَا يُلَاقِي الْهَوَانَا"],["وَلَوَ انَّ الْحَيَاةَ تَبْقَى لِحَيٍّ","لَعَدَدْنَا أَضَلَّنَا الشُّجْعَانَا"],["وَإِذَا لَمْ يَكُنْ مِنَ الْمَوْتِ بُدٌّ","فَمِنَ الْعَجْزِ أَنْ تَكُونَ جَبَانَا"],["كُلُّ مَا لَمْ يَكُنْ مِنَ الصَّعْبِ فِي الْأَنْـ","ـفُسِ سَهْلٌ فِيهَا إِذَا هُوَ كَانَا"],["أُطَاعِنُ خَيْلًا مِنْ فَوَارِسِهَا الدَّهْرُ","وَحِيدًا وَمَا قَوْلِي كَذَا وَمَعِي الصَّبْرُ"],["وَأَشْجَعُ مِنِّي كُلَّ يَوْمٍ سَلَامَتِي","وَمَا ثَبَتَتْ إِلَّا وَفِي نَفْسِهَا أَمْرُ"],["تَمَرَّسْتُ بِالْآفَاتِ حَتَّى تَرَكْتُهَا","تَقُولُ أَمَاتَ الْمَوْتُ أَمْ ذُعِرَ الذُّعْرُ"],["وَأَقْدَمْتُ إِقْدَامَ الْأَتِيِّ كَأَنَّ لِي","سِوَى مُهْجَتِي أَوْ كَانَ لِي عِنْدَهَا وِتْرُ"],["ذَرِ النَّفْسَ تَأْخُذْ وُسْعَهَا قَبْلَ بَيْنِهَا","فَمُفْتَرِقٌ جَارَانِ دَارُهُمَا الْعُمْرُ"],["سَيَعْلَمُ الْجَمْعُ مِمَّنْ ضَمَّ مَجْلِسُنَا","بِأَنَّنِي خَيْرُ مَنْ تَسْعَى بِهِ قَدَمُ"],["أَنَا الَّذِي نَظَرَ الْأَعْمَى إِلَى أَدَبِي","وَأَسْمَعَتْ كَلِمَاتِي مَنْ بِهِ صَمَمُ"],["الْخَيْلُ وَاللَّيْلُ وَالْبَيْدَاءُ تَعْرِفُنِي","وَالسَّيْفُ وَالرُّمْحُ وَالْقِرْطَاسُ وَالْقَلَمُ"],["فَتًى مَاتَ بَيْنَ الضَّرْبِ وَالطَّعْنِ مِيتَةً","تَقُومُ مَقَامَ النَّصْرِ إِذْ فَاتَهُ النَّصْرُ"],["وَمَا مَاتَ حَتَّى مَاتَ مَضْرِبُ سَيْفِهِ","مِنَ الضَّرْبِ وَاعْتَلَّتْ عَلَيْهِ الْقَنَا السُّمْرُ"],["وَقَدْ كَانَ فَوْتُ الْمَوْتِ سَهْلًا فَرَدَّهُ","إِلَيْهِ الْحِفَاظُ الْمُرُّ وَالْخُلُقُ الْوَعْرُ"],["وَنَفْسٌ تَعَافُ الْعَارَ حَتَّى كَأَنَّهُ","هُوَ الْكُفْرُ يَوْمَ الرَّوْعِ أَوْ دُونَهُ الْكُفْرُ"],["فَأَثْبَتَ فِي مُسْتَنْقَعِ الْمَوْتِ رِجْلَهُ","وَقَالَ لَهَا مِنْ تَحْتِ أَخْمَصِكِ الْحَشْرُ"],["غَدَا غَدْوَةً وَالْحَمْدُ نَسْجُ رِدَائِهِ","فَلَمْ يَنْصَرِفْ إِلَّا وَأَكْفَانُهُ الْأَجْرُ"],["تَرَدَّى ثِيَابَ الْمَوْتِ حُمْرًا فَمَا أَتَى","لَهَا اللَّيْلُ إِلَّا وَهْيَ مِنْ سُنْدُسٍ خُضْرُ"],["سَيَذْكُرُنِي قَوْمِي إِذَا جَدَّ جِدُّهُمْ","وَفِي اللَّيْلَةِ الظَّلْمَاءِ يُفْتَقَدُ الْبَدْرُ"],["وَنَحْنُ أُنَاسٌ لَا تَوَسُّطَ عِنْدَنَا","لَنَا الصَّدْرُ دُونَ الْعَالَمِينَ أَوِ الْقَبْرُ"],["تَهُونُ عَلَيْنَا فِي الْمَعَالِي نُفُوسُنَا","وَمَنْ خَطَبَ الْحَسْنَاءَ لَمْ يُغْلِهَا الْمَهْرُ"],["أَبَا هِنْدٍ فَلَا تَعْجَلْ عَلَيْنَا","وَأَنْظِرْنَا نُخَبِّرْكَ الْيَقِينَا"],["بِأَنَّا نُورِدُ الرَّايَاتِ بِيضًا","وَنُصْدِرُهُنَّ حُمْرًا قَدْ رَوِينَا"],["وَنَشْرَبُ إِنْ وَرَدْنَا الْمَاءَ صَفْوًا","وَيَشْرَبُ غَيْرُنَا كَدِرًا وَطِينَا"],["تَعَزَّ فَإِنَّ الصَّبْرَ بِالْحُرِّ أَجْمَلُ","وَلَيْسَ عَلَى رَيْبِ الزَّمَانِ مُعَوَّلُ"],["فَلَوْ كَانَ يُغْنِي أَنْ يُرَى الْمَرْءُ جَازِعًا","لِحَادِثَةٍ أَوْ كَانَ يُغْنِي التَّذَلُّلُ"],["لَكَانَ التَّعَزِّي عِنْدَ كُلِّ مُصِيبَةٍ","وَنَائِبَةٍ بِالْحُرِّ أَوْلَى وَأَجْمَلُ"],["فَكَيْفَ وَكُلٌّ لَيْسَ يَعْدُو حِمَامَهُ","وَمَا لِامْرِئٍ عَمَّا قَضَى اللَّهُ مَرْحَلُ"],["فَإِنْ تَكُنِ الْأَيَّامُ فِينَا تَبَدَّلَتْ","بِبُؤْسَى وَنُعْمَى وَالْحَوَادِثُ تَفْعَلُ"],["فَمَا لَيَّنَتْ مِنَّا قَنَاةً صَلِيبَةً","وَلَا ذَلَّلَتْنَا لِلَّتِي لَيْسَ تَجْمُلُ"],["وَلَكِنْ رَحَلْنَاهَا نُفُوسًا كَرِيمَةً","تُحَمَّلُ مَا لَا يُسْتَطَاعُ فَتَحْمِلُ"],["وَقَيْنَا بِحُسْنِ الصَّبْرِ مِنَّا نُفُوسَنَا","فَصَحَّتْ لَنَا الْأَعْرَاضُ وَالنَّاسُ هُزَّلُ"],["قَالَتْ حُبِسْتَ فَقُلْتُ لَيْسَ بِضَائِرٍ","حَبْسِي وَأَيُّ مُهَنَّدٍ لَا يُغْمَدُ"],["أَوَمَا رَأَيْتِ اللَّيْثَ يَأْلَفُ غِيلَهُ","كِبْرًا وَأَوْبَاشُ السِّبَاعِ تَرَدَّدُ"],["وَالشَّمْسُ لَوْلَا أَنَّهَا مَحْجُوبَةٌ","عَنْ نَاظِرَيْكِ لَمَا أَضَاءَ الْفَرْقَدُ"],["وَالْبَدْرُ يُدْرِكُهُ السِّرَارُ فَتَنْجَلِي","أَيَّامُهُ وَكَأَنَّهُ مُتَجَدِّدُ"],["وَالنَّارُ فِي أَحْجَارِهَا مَخْبُوءَةٌ","لَا تُصْطَلَى إِنْ لَمْ تُثِرْهَا الْأَزْنُدُ"],["وَالزَّاعِبِيَّةُ لَا يُقِيمُ كُعُوبَهَا","إِلَّا الثِّقَافُ وَجَذْوَةٌ تَتَوَقَّدُ"],["وَلِكُلِّ حَالٍ مُعْقِبٌ وَلَرُبَّمَا","أَجْلَى لَكَ الْمَكْرُوهُ عَمَّا يُحْمَدُ"],["لَا يُؤْيِسَنَّكَ مِنْ تَفَرُّجِ كُرْبَةٍ","خَطْبٌ رَمَاكَ بِهِ الزَّمَانُ الْأَنْكَدُ"],["كَمْ مِنْ عَلِيلٍ قَدْ تَخَطَّاهُ الرَّدَى","فَنَجَا وَمَاتَ طَبِيبُهُ وَالْعُوَّدُ"],["لَيْسَ الْجَمَالُ بِمِئْزَرٍ","فَاعْلَمْ وَإِنْ رُدِّيتَ بُرْدَا"],["إِنَّ الْجَمَالَ مَعَادِنٌ","وَمَنَاقِبٌ أَوْرَثْنَ مَجْدَا"],["كُلُّ امْرِئٍ يَجْرِي إِلَى","يَوْمِ الْهِيَاجِ بِمَا اسْتَعَدَّا"],["كَمْ مِنْ أَخٍ لِيَ صَالِحٍ","بَوَّأْتُهُ بِيَدَيَّ لَحْدَا"],["مَا إِنْ جَزِعْتُ وَلَا هَلِعْـ","ـتُ وَلَا يَرُدُّ بُكَايَ زَنْدَا"],["أَلْبَسْتُهُ أَثْوَابَهُ","وَخُلِقْتُ يَوْمَ خُلِقْتُ جَلْدَا"],["أُغْنِي غَنَاءَ الذَّاهِبِيـ","ـنَ أُعَدُّ لِلْأَعْدَاءِ عَدَّا"],["ذَهَبَ الَّذِينَ أُحِبُّهُمْ","وَبَقِيتُ مِثْلَ السَّيْفِ فَرْدَا"],["إِذَا الْمَرْءُ لَمْ يَحْتَلْ وَقَدْ جَدَّ جِدُّهُ","أَضَاعَ وَقَاسَى أَمْرَهُ وَهْوَ مُدْبِرُ"],["وَلَكِنْ أَخُو الْحَزْمِ الَّذِي لَيْسَ نَازِلًا","بِهِ الْخَطْبُ إِلَّا وَهْوَ لِلْقَصْدِ مُبْصِرُ"],["فَذَاكَ قَرِيعُ الدَّهْرِ مَا عَاشَ حُوَّلٌ","إِذَا سُدَّ مِنْهُ مَنْخِرٌ جَاشَ مَنْخِرُ"],["إِذَا غَامَرْتَ فِي شَرَفٍ مَرُومٍ","فَلَا تَقْنَعْ بِمَا دُونَ النُّجُومِ"],["فَطَعْمُ الْمَوْتِ فِي أَمْرٍ حَقِيرٍ","كَطَعْمِ الْمَوْتِ فِي أَمْرٍ عَظِيمِ"],["يَرَى الْجُبَنَاءُ أَنَّ الْعَجْزَ عَقْلٌ","وَتِلْكَ خَدِيعَةُ الطَّبْعِ اللَّئِيمِ"],["وَكُلُّ شَجَاعَةٍ فِي الْمَرْءِ تُغْنِي","وَلَا مِثْلَ الشَّجَاعَةِ فِي الْحَكِيمِ"],["وَكَمْ مِنْ عَائِبٍ قَوْلًا صَحِيحًا","وَآفَتُهُ مِنَ الْفَهْمِ السَّقِيمِ"],["وَلَكِنْ تَأْخُذُ الْآذَانُ مِنْهُ","عَلَى قَدْرِ الْقَرَائِحِ وَالْعُلُومِ"],["عَلَى قَدْرِ أَهْلِ الْعَزْمِ تَأْتِي الْعَزَائِمُ","وَتَأْتِي عَلَى قَدْرِ الْكِرَامِ الْمَكَارِمُ"],["وَتَعْظُمُ فِي عَيْنِ الصَّغِيرِ صِغَارُهَا","وَتَصْغُرُ فِي عَيْنِ الْعَظِيمِ الْعَظَائِمُ"],["سِوَايَ بِتَحْنَانِ الْأَغَارِيدِ يَطْرَبُ","وَغَيْرِيَ بِاللَّذَّاتِ يَلْهُو وَيُعْجَبُ"],["وَمَا أَنَا مِمَّنْ تَأْسِرُ الْخَمْرُ لُبَّهُ","وَيَمْلِكُ سَمْعَيْهِ الْيَرَاعُ الْمُثَقَّبُ"],["وَلَكِنْ أَخُو هَمٍّ إِذَا مَا تَرَجَّحَتْ","بِهِ سَوْرَةٌ نَحْوَ الْعُلَا رَاحَ يَدْأَبُ"],["نَفَى النَّوْمَ عَنْ عَيْنَيْهِ نَفْسٌ أَبِيَّةٌ","لَهَا بَيْنَ أَطْرَافِ الْأَسِنَّةِ مَطْلَبُ"],["هَمَامَةُ نَفْسٍ أَصْغَرَتْ كُلَّ مَأْرَبٍ","فَكَلَّفَتِ الْأَيَّامَ مَا لَيْسَ يُوهَبُ"],["وَمَنْ تَكُنِ الْعَلْيَاءُ هِمَّةَ نَفْسِهِ","فَكُلُّ الَّذِي يَلْقَاهُ فِيهَا مُحَبَّبُ"],["إِذَا أَنَا لَمْ أُعْطِ الْمَكَارِمَ حَقَّهَا","فَلَا عَزَّنِي خَالٌ وَلَا ضَمَّنِي أَبُ"],["خُلِقْتُ عَيُوفًا لَا أَرَى لِابْنِ حُرَّةٍ","لَدَيَّ يَدًا أُغْضِي لَهَا حِينَ يَغْضَبُ"],["أَصَالَةُ الرَّأْيِ صَانَتْنِي عَنِ الْخَطَلِ","وَحِلْيَةُ الْفَضْلِ زَانَتْنِي لَدَى الْعَطَلِ"],["حُبُّ السَّلَامَةِ يَثْنِي هَمَّ صَاحِبِهِ","عَنِ الْمَعَالِي وَيُغْرِي الْمَرْءَ بِالْكَسَلِ"],["إِنَّ الْعُلَى حَدَّثَتْنِي وَهْيَ صَادِقَةٌ","فِي مَا تُحَدِّثُ أَنَّ الْعِزَّ فِي النُّقَلِ"],["سَلِي الرِّمَاحَ الْعَوَالِي عَنْ مَعَالِينَا","وَاسْتَشْهِدِي الْبِيضَ هَلْ خَابَ الرَّجَا فِينَا"],["إِنَّا لَقَوْمٌ أَبَتْ أَخْلَاقُنَا شَرَفًا","أَنْ نَبْتَدِي بِالْأَذَى مَنْ لَيْسَ يُؤْذِينَا"],["بِيضٌ صَنَائِعُنَا سُودٌ وَقَائِعُنَا","خُضْرٌ مَرَابِعُنَا حُمْرٌ مَوَاضِينَا"],["لَا يَظْهَرُ الْعَجْزُ مِنَّا دُونَ نَيْلِ مُنًى","وَلَوْ رَأَيْنَا الْمَنَايَا فِي أَمَانِينَا"],["إِذَا جَرَيْنَا إِلَى سَبْقِ الْعُلَى طَلَقًا","إِنْ لَمْ نَكُنْ سُبَّقًا كُنَّا مُصَلِّينَا"],["نَغْشَى الْخُطُوبَ بِأَيْدِينَا فَنَدْفَعُهَا","وَإِنْ دَهَتْنَا دَفَعْنَاهَا بِأَيْدِينَا"],["تَرَى الرَّجُلَ النَّحِيفَ فَتَزْدَرِيهِ","وَفِي أَثْوَابِهِ أَسَدٌ مُزِيرُ"],["وَيُعْجِبُكَ الطَّرِيرُ فَتَبْتَلِيهِ","فَيُخْلِفُ ظَنَّكَ الرَّجُلُ الطَّرِيرُ"],["فَمَا عِظَمُ الرِّجَالِ لَهُمْ بِفَخْرٍ","وَلَكِنْ فَخْرُهُمْ كَرَمٌ وَخَيْرُ"],["بُغَاثُ الطَّيْرِ أَكْثَرُهَا فِرَاخًا","وَأُمُّ الصَّقْرِ مِقْلَاةٌ نَزُورُ"],["لَقَدْ عَظُمَ الْبَعِيرُ بِغَيْرِ لُبٍّ","فَلَمْ يَسْتَغْنِ بِالْعِظَمِ الْبَعِيرُ"],["يُصَرِّفُهُ الصَّبِيُّ بِكُلِّ وَجْهٍ","وَيَحْبِسُهُ عَلَى الْخَسْفِ الْجَرِيرُ"],["يُعَاتِبُنِي فِي الدَّيْنِ قَوْمِي وَإِنَّمَا","دُيُونِيَ فِي أَشْيَاءَ تُكْسِبُهُمْ حَمْدَا"],["أَسُدُّ بِهِ مَا قَدْ أَخَلُّوا وَضَيَّعُوا","ثُغُورَ حُقُوقٍ مَا أَطَاقُوا لَهَا سَدَّا"],["وَإِنَّ الَّذِي بَيْنِي وَبَيْنَ بَنِي أَبِي","وَبَيْنَ بَنِي عَمِّي لَمُخْتَلِفٌ جِدَّا"],["فَإِنْ أَكَلُوا لَحْمِي وَفَرْتُ لُحُومَهُمْ","وَإِنْ هَدَمُوا مَجْدِي بَنَيْتُ لَهُمْ مَجْدَا"],["وَإِنْ ضَيَّعُوا غَيْبِي حَفِظْتُ غُيُوبَهُمْ","وَإِنْ هُمْ هَوُوا غَيِّي هَوِيتُ لَهُمْ رُشْدَا"],["وَإِنْ زَجَرُوا طَيْرًا بِنَحْسٍ تَمُرُّ بِي","زَجَرْتُ لَهُمْ طَيْرًا تَمُرُّ بِهِمْ سَعْدَا"],["وَلَا أَحْمِلُ الْحِقْدَ الْقَدِيمَ عَلَيْهِمُ","وَلَيْسَ رَئِيسُ الْقَوْمِ مَنْ يَحْمِلُ الْحِقْدَا"],["لَهُمْ جُلُّ مَالِي إِنْ تَتَابَعَ لِي غِنًى","وَإِنْ قَلَّ مَالِي لَمْ أُكَلِّفْهُمُ رِفْدَا"],["وَإِنِّي لَعَبْدُ الضَّيْفِ مَا دَامَ نَازِلًا","وَمَا شِيمَةٌ لِي غَيْرَهَا تُشْبِهُ الْعَبْدَا"],["أَمَاوِيُّ إِنَّ الْمَالَ غَادٍ وَرَائِحٌ","وَيَبْقَى مِنَ الْمَالِ الْأَحَادِيثُ وَالذِّكْرُ"],["أَمَاوِيُّ إِنِّي لَا أَقُولُ لِسَائِلٍ","إِذَا جَاءَ يَوْمًا حَلَّ فِي مَالِنَا نَزْرُ"],["أَمَاوِيُّ إِمَّا مَانِعٌ فَمُبَيَّنٌ","وَإِمَّا عَطَاءٌ لَا يُنَهْنِهُهُ الزَّجْرُ"],["أَمَاوِيُّ مَا يُغْنِي الثَّرَاءُ عَنِ الْفَتَى","إِذَا حَشْرَجَتْ نَفْسٌ وَضَاقَ بِهَا الصَّدْرُ"],["وَقَدْ عَلِمَ الْأَقْوَامُ لَوْ أَنَّ حَاتِمًا","أَرَادَ ثَرَاءَ الْمَالِ كَانَ لَهُ وَفْرُ"],["وَإِنِّيَ لَا آلُو بِمَالٍ صَنِيعَةً","فَأَوَّلُهُ زَادٌ وَآخِرُهُ ذُخْرُ"],["فَمَا زَادَنَا بَأْوًا عَلَى ذِي قَرَابَةٍ","غِنَانَا وَلَا أَزْرَى بِأَحْسَابِنَا الْفَقْرُ"],["لَحَى اللَّهُ صُعْلُوكًا إِذَا جَنَّ لَيْلُهُ","مُصَافِي الْمُشَاشِ آلِفًا كُلَّ مَجْزَرِ"],["يَعُدُّ الْغِنَى مِنْ نَفْسِهِ كُلَّ لَيْلَةٍ","أَصَابَ قِرَاهَا مِنْ صَدِيقٍ مُيَسَّرِ"],["يَنَامُ عِشَاءً ثُمَّ يُصْبِحُ نَاعِسًا","يَحُتُّ الْحَصَى عَنْ جَنْبِهِ الْمُتَعَفِّرِ"],["وَلَكِنَّ صُعْلُوكًا صَفِيحَةُ وَجْهِهِ","كَضَوْءِ شِهَابِ الْقَابِسِ الْمُتَنَوِّرِ"],["مُطِلًّا عَلَى أَعْدَائِهِ يَزْجُرُونَهُ","بِسَاحَتِهِمْ زَجْرَ الْمَنِيحِ الْمُشَهَّرِ"],["إِذَا بَعُدُوا لَا يَأْمَنُونَ اقْتِرَابَهُ","تَشَوُّفَ أَهْلِ الْغَائِبِ الْمُتَنَظَّرِ"],["فَذَلِكَ إِنْ يَلْقَ الْمَنِيَّةَ يَلْقَهَا","حَمِيدًا وَإِنْ يَسْتَغْنِ يَوْمًا فَأَجْدَرِ"],["دَعِينِي أُطَوِّفْ فِي الْبِلَادِ لَعَلَّنِي","أُفِيدُ غِنًى فِيهِ لِذِي الْحَقِّ مُحْمِلُ"],["أَلَيْسَ عَظِيمًا أَنْ تُلِمَّ مُلِمَّةٌ","وَلَيْسَ عَلَيْنَا فِي الْحُقُوقِ مُعَوَّلُ"],["فَإِنْ نَحْنُ لَمْ نَمْلِكْ دِفَاعًا بِحَادِثٍ","تُلِمُّ بِهِ الْأَيَّامُ فَالْمَوْتُ أَجْمَلُ"]],"secs":{"1":"في الإباء وعزة النفس — المنسوب إلى عنترة: حكّم سيوفك في رقاب العذّل","10":"في الإباء وعزة النفس — المتنبي: عش عزيزًا أو مت وأنت كريم","17":"في الإباء وعزة النفس — المتنبي: لا افتخار إلا لمن لا يضام","23":"في الإباء وعزة النفس — قريط بن أنيف العنبري: لو كنت من مازن لم تستبح إبلي","31":"في الإباء وعزة النفس — الشنفرى: وفي الأرض منأى للكريم عن الأذى (من لامية العرب)","34":"في الإباء وعزة النفس — الشريف الرضي: لغير العلى مني القلى والتجنب","41":"في الإباء وعزة النفس — المنسوب إلى الشافعي: أنا إن عشت لست أعدم قوتًا","44":"في الإباء وعزة النفس — السموأل: إذا المرء لم يدنس من اللؤم عرضه","47":"في الشجاعة والإقدام — قطري بن الفجاءة: أقول لها وقد طارت شعاعًا","54":"في الشجاعة والإقدام — الحصين بن الحمام المري: تأخرت أستبقي الحياة فلم أجد","57":"في الشجاعة والإقدام — عمرو بن الإطنابة: أبت لي عفتي وأبى بلائي","61":"في الشجاعة والإقدام — سعد بن ناشب المازني: سأغسل عني العار بالسيف جالبًا","68":"في الشجاعة والإقدام — بشامة بن حزن النهشلي: إنا بني نهشل لا ندعي لأب","75":"في الشجاعة والإقدام — المتنبي: الرأي قبل شجاعة الشجعان","80":"في الشجاعة والإقدام — المتنبي: وإذا لم يكن من الموت بد","85":"في الشجاعة والإقدام — المتنبي: أطاعن خيلًا من فوارسها الدهر","90":"في الشجاعة والإقدام — المتنبي: الخيل والليل والبيداء تعرفني","93":"في الشجاعة والإقدام — أبو تمام: فتى مات بين الضرب والطعن ميتة","100":"في الشجاعة والإقدام — أبو فراس الحمداني: سيذكرني قومي إذا جد جدهم","103":"في الشجاعة والإقدام — عمرو بن كلثوم: أبا هند فلا تعجل علينا (من المعلقة)","106":"في الصبر على الشدائد — إبراهيم بن كنيف النبهاني: تعزّ فإن الصبر بالحر أجمل","114":"في الصبر على الشدائد — علي بن الجهم: قالت حبست فقلت ليس بضائرٍ","123":"في الصبر على الشدائد — عمرو بن معدي كرب: ليس الجمال بمئزر","131":"في الصبر على الشدائد — تأبط شرًّا: إذا المرء لم يحتل وقد جد جده","134":"في علو الهمة — المتنبي: إذا غامرت في شرف مروم","140":"في علو الهمة — المتنبي: على قدر أهل العزم تأتي العزائم","142":"في علو الهمة — البارودي: سواي بتحنان الأغاريد يطرب","150":"في علو الهمة — الطغرائي: أصالة الرأي صانتني عن الخطل (من لامية العجم)","153":"في علو الهمة — صفي الدين الحلي: سلي الرماح العوالي عن معالينا","159":"في علو الهمة — العباس بن مرداس: ترى الرجل النحيف فتزدريه","165":"في الوفاء والكرم — المقنع الكندي: يعاتبني في الدين قومي وإنما","174":"في الوفاء والكرم — حاتم الطائي: أماويّ إن المال غادٍ ورائح","181":"في الوفاء والكرم — عروة بن الورد: لحى الله صعلوكًا إذا جن ليله","188":"في الوفاء والكرم — عروة بن الورد: دعيني أطوّف في البلاد لعلني"}}],"sharh":false};
